-- READ-ONLY exact-open-gap aggregate; bounded by frozen UTC candidate intervals.
SELECT gap_id,COUNT(*) AS source_rows,SUM(MOD(`dateTime`,300)=0) AS on_300s_grid,SUM(MOD(`dateTime`,300)<>0) AS off_300s_grid,COUNT(DISTINCT `usUnits`) AS distinct_usUnits,MIN(`usUnits`) AS min_usUnits,MAX(`usUnits`) AS max_usUnits,COUNT(DISTINCT `interval`) AS distinct_intervals,MIN(`interval`) AS min_interval,MAX(`interval`) AS max_interval,MIN(`dateTime`) AS first_source_ts,MAX(`dateTime`) AS last_source_ts,SUM(`outTemp` IS NOT NULL) AS nonnull_outTemp, SUM(`outHumidity` IS NOT NULL) AS nonnull_outHumidity, SUM(`rain` IS NOT NULL) AS nonnull_rain, SUM(`rainRate` IS NOT NULL) AS nonnull_rainRate, SUM(`windSpeed` IS NOT NULL) AS nonnull_windSpeed, SUM(`windGust` IS NOT NULL) AS nonnull_windGust, SUM(`barometer` IS NOT NULL) AS nonnull_barometer,SUM(`outTemp`=0) AS outTemp_zero_values FROM (SELECT CASE WHEN `dateTime`>1737698100 AND `dateTime`<1737726900 THEN 1 WHEN `dateTime`>1753792500 AND `dateTime`<1753800300 THEN 2 WHEN `dateTime`>1754653800 AND `dateTime`<1754658300 THEN 3 WHEN `dateTime`>1755168000 AND `dateTime`<1755240000 THEN 4 WHEN `dateTime`>1755496500 AND `dateTime`<1755519300 THEN 5 WHEN `dateTime`>1757604300 AND `dateTime`<1757608200 THEN 6 WHEN `dateTime`>1766086200 AND `dateTime`<1766125500 THEN 7 WHEN `dateTime`>1767206400 AND `dateTime`<1767221400 THEN 8 ELSE NULL END AS gap_id,`dateTime`,`usUnits`,`interval`,`outTemp`,`outHumidity`,`rain`,`rainRate`,`windSpeed`,`windGust`,`barometer` FROM `pocasi-loucka.eu_old`.`archive` WHERE (`dateTime`>1737698100 AND `dateTime`<1737726900) OR (`dateTime`>1753792500 AND `dateTime`<1753800300) OR (`dateTime`>1754653800 AND `dateTime`<1754658300) OR (`dateTime`>1755168000 AND `dateTime`<1755240000) OR (`dateTime`>1755496500 AND `dateTime`<1755519300) OR (`dateTime`>1757604300 AND `dateTime`<1757608200) OR (`dateTime`>1766086200 AND `dateTime`<1766125500) OR (`dateTime`>1767206400 AND `dateTime`<1767221400)) q WHERE gap_id IS NOT NULL GROUP BY gap_id ORDER BY gap_id;
